"""Reviewer contract: all-three judging, deterministic pre-check, pydantic
course correction, fail closed."""

from __future__ import annotations

import json

from live_evidence.reviewer import (
    REVIEWER_PROMPT,
    AnswerReviewer,
    _parse_review,
)


def test_deterministic_scannability_precheck_is_weak_without_model(monkeypatch) -> None:
    reviewer = AnswerReviewer()

    def must_not_call(*args, **kwargs):  # noqa: ANN002, ANN003
        raise AssertionError("model must not be called for a deterministic scannability failure")

    monkeypatch.setattr(reviewer, "_complete", must_not_call)
    prose = (
        "I would begin with shadow mode that generates but never shows responses, "
        "comparing claims and escalation decisions with human outcomes, then move to "
        "agent assist where a human edits or approves each response before it ships."
    )
    outcome = reviewer.review("Propose a rollout", prose, "transcript")
    assert outcome.verdict == "weak"
    assert outcome.deterministic is True
    assert outcome.reasons and outcome.reasons[0].startswith("SCANNABILITY:")
    assert "flashcard" in outcome.amendment_instruction


def test_parse_review_valid_weak_verdict() -> None:
    raw = json.dumps(
        {
            "verdict": "weak",
            "reasons": ["STALENESS: answer ignores the SLO constraint added at 12:41"],
            "amendment_instruction": "Add the p95 latency SLO the interviewer specified.",
        }
    )
    outcome = _parse_review(raw, elapsed_s=0.1)
    assert outcome.error is None
    assert outcome.verdict == "weak"
    assert outcome.reasons[0].startswith("STALENESS:")


def test_parse_review_rejects_invalid_verdict_with_detail() -> None:
    raw = json.dumps({"verdict": "mediocre", "reasons": [], "amendment_instruction": ""})
    outcome = _parse_review(raw, elapsed_s=0.1)
    assert outcome.error == "schema_validation_failed"
    assert "verdict" in (outcome.error_detail or "")


def test_course_correction_then_fail_closed(monkeypatch) -> None:
    monkeypatch.setattr("live_evidence.reviewer.reviewer_key", lambda: "test-key")
    reviewer = AnswerReviewer()
    bad = json.dumps({"verdict": "fine"})
    good = json.dumps({"verdict": "ok", "reasons": [], "amendment_instruction": ""})
    calls: list[int] = []

    sequences: list[list[dict[str, str]]] = []

    def corrects(messages, key):
        calls.append(len(messages))
        sequences.append([dict(m) for m in messages])
        return (bad if len(calls) == 1 else good), None

    monkeypatch.setattr(reviewer, "_complete", corrects)
    scannable_answer = "- Raft consensus\n- Quorum R + W > N"
    outcome = reviewer.review("How does consensus work?", scannable_answer, "transcript")
    assert outcome.verdict == "ok"
    assert outcome.course_corrected is True
    assert len(calls) == 2
    # Correction safety: the rejected raw response is not echoed back.
    assert sequences[1][-1]["role"] == "user"
    assert len(sequences[1]) == 2
    assert bad not in sequences[1][-1]["content"]

    calls.clear()

    def always_bad(messages, key):
        calls.append(len(messages))
        return bad, None

    monkeypatch.setattr(reviewer, "_complete", always_bad)
    outcome = reviewer.review("How does consensus work?", scannable_answer, "transcript")
    assert outcome.error == "schema_validation_failed"
    assert len(calls) == 2  # exactly one correction round, then closed


def test_prompt_judges_exactly_three_things() -> None:
    assert "CORRECTNESS" in REVIEWER_PROMPT
    assert "SCANNABILITY" in REVIEWER_PROMPT
    assert "STALENESS" in REVIEWER_PROMPT
    assert "Return one JSON object and no other text" in REVIEWER_PROMPT
    assert "Do not judge tone, preference, eloquence, or formatting" in REVIEWER_PROMPT
    # Publication boundary + required inputs are in the contract.
    assert "QUESTION_EVENTS_AFTER_PUBLICATION" in REVIEWER_PROMPT
    assert "EVIDENCE_EXCERPTS_USED" in REVIEWER_PROMPT
    # Schema-last assembly.
    assert REVIEWER_PROMPT.rstrip().endswith("additional keys.")
